// --- flow context: счётчик, живущий между сообщениями -----------------
let counter = flow.get("krupa_counter");
if (typeof counter !== "number") {
    counter = 0;
}
counter = counter + 1;
flow.set("krupa_counter", counter);

// --- global context: журнал последних 5 тиков -------------------------
let history = global.get("krupa_history");
if (!Array.isArray(history)) {
    history = [];
}
history.push({ n: counter, at: new Date().toISOString(), value: msg.payload });
if (history.length > 5) {
    history = history.slice(history.length - 5);
}
global.set("krupa_history", history);

// --- environment variables -------------------------------------------
const envStudent = env.get("LAB2_STUDENT") || "(переменная не задана)";
const envLab = env.get("LAB2_LAB") || "(переменная не задана)";

msg.topic = "lab2/krupa/context";
msg.payload = {
    student: "Крупа Ксения",
    counter: counter,
    counterStorage: "flow context (node: f12_fn_counter)",
    historyLength: history.length,
    history: history,
    environment: {
        LAB2_STUDENT: envStudent,
        LAB2_LAB: envLab
    }
};

return msg;

// Сбрасываем flow context и чистим global context.
flow.set("krupa_counter", 0);
global.set("krupa_history", []);

msg.topic = "lab2/krupa/context";
msg.payload = {
    student: "Крупа Ксения",
    action: "reset",
    counter: 0,
    message: "Счётчик в flow context сброшен в 0, global history очищена"
};
return msg;
